(function(){'use strict';
const KEY='nawaf-hq-v5';
const VIEWS=['dashboard','workforce','projects','tasks','reports'];
const COMMANDS=[['research','بحث عميق'],['analyze','تحليل'],['plan','خطة تنفيذ'],['review','مراجعة جودة'],['ideas','ابتكار أفكار'],['solve','حل مشكلة'],['compare','مقارنة'],['report','إعداد تقرير'],['custom','أمر مخصص']];
const EXTERNAL=/عدل|عدّل|اصلح|أصلح|اضف|أضف|احذف|حذف|نفذ|نفّذ|برمج|كود|واجهة|زر|صفحة|ميزة|مشكلة|خطأ|bug|fix|implement|update|change|deploy/i;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason='v8'){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function seed(){const s=read();let changed=false;if(!Array.isArray(s.employees)||!s.employees.length){s.employees=[{id:'sara',name:'سارة',role:'المدير العام AI',department:'الإدارة العامة',status:'READY'},{id:'omar',name:'عمر',role:'قائد التقنية والبحث',department:'التقنية والبحث',status:'READY'},{id:'lian',name:'ليان',role:'قائدة المنتج والتجربة',department:'المنتج والتجربة',status:'READY'},{id:'noura',name:'نورة',role:'قائدة الجودة والمراجعة',department:'الجودة والمراجعة',status:'READY'}];changed=true}if(!Array.isArray(s.projects)||!s.projects.length){s.projects=[{id:'mueen',name:'مُعِين',status:'ACTIVE',phase:'جاهز للعمل',progress:0},{id:'qaddha',name:'قدّها',status:'ACTIVE',phase:'جاهز للعمل',progress:0},{id:'nav',name:'ناڤ',status:'PAUSED',phase:'متوقف مؤقتًا',progress:0}];changed=true}for(const k of ['tasks','reports','activity','approvals'])if(!Array.isArray(s[k])){s[k]=[];changed=true}if(changed)localStorage.setItem(KEY,JSON.stringify(s));return s}
function status(v){return({READY:'جاهز',IDLE:'متاح',WORKING:'يعمل الآن',RESEARCHING:'يبحث الآن',REVIEWING:'يراجع',WAITING_FOR_NAWAF:'بانتظارك',BLOCKED_BY_TOOL:'متوقف بسبب أداة',BLOCKED:'فشل التنفيذ',COMPLETED:'مكتمل',PAUSED:'متوقف مؤقتًا'})[v]||v||'جاهز'}
function projectUrl(id){return id==='mueen'?'https://mueen-islamic-app.vercel.app/':id==='qaddha'?'https://qaddha.vercel.app/':''}
function repoUrl(id){return id==='mueen'?'https://github.com/uauz1/mueen-islamic-app':id==='qaddha'?'https://github.com/uauz1/game':''}
let view='dashboard';
function stat(s){const busy=s.employees.filter(e=>['WORKING','RESEARCHING','REVIEWING'].includes(e.status)).length,done=s.tasks.filter(t=>t.status==='COMPLETED').length,waiting=s.tasks.filter(t=>t.status==='WAITING_FOR_NAWAF').length;return {busy,done,waiting}}
function nav(){return `<aside class="v8-side"><div class="v8-brand"><b>NAWAF <span>HQ</span></b><small>AI COMPANY OPERATING SYSTEM</small></div><nav>${[['dashboard','الرئيسية'],['workforce','الموظفون'],['projects','المشاريع'],['tasks','المهام'],['reports','التقارير']].map(([id,label])=>`<button type="button" data-view="${id}" class="${view===id?'active':''}"><span>${label}</span></button>`).join('')}</nav><div class="v8-ready">● SYSTEM READY<small>واجهة مستقرة وخفيفة بدون 3D</small></div></aside>`}
function top(title,sub){return `<header class="v8-header"><div><span class="v8-kicker">AI WORKFORCE COMMAND CENTER</span><h1>${title}</h1><p>${sub}</p></div><div class="v8-actions"><button class="v8-btn" type="button" data-action="new-employee">＋ موظف</button><button class="v8-btn primary" type="button" data-action="company-command">✦ توجيه الشركة</button></div></header>`}
function stats(s){const x=stat(s);return `<section class="v8-stats"><article><b>${s.employees.length}</b><span>الموظفون</span></article><article><b>${x.busy}</b><span>يعمل الآن</span></article><article><b>${s.tasks.length}</b><span>المهام</span></article><article><b>${x.done}</b><span>مكتمل</span></article><article><b>${x.waiting}</b><span>بانتظارك</span></article></section>`}
function person(e){return `<button type="button" class="v8-person" data-employee="${esc(e.id)}"><span class="v8-avatar">${esc((e.name||'AI').slice(0,1))}</span><span><b>${esc(e.name)}</b><small>${esc(e.role||e.department||'موظف AI')}</small></span><span class="v8-status">${esc(status(e.status))}</span></button>`}
function projectCard(p){const live=projectUrl(p.id),repo=repoUrl(p.id);return `<article class="v8-project"><div><b>${esc(p.name)}</b><small>${esc(p.phase||'جاهز للعمل')} • ${esc(p.status||'ACTIVE')}</small></div><div class="v8-project-actions">${live?`<a href="${live}" target="_blank" rel="noopener noreferrer">فتح الموقع</a>`:''}${repo?`<a href="${repo}" target="_blank" rel="noopener noreferrer">GitHub</a>`:''}<button type="button" data-project="${esc(p.id)}">إدارة</button></div></article>`}
function taskRow(t,s){const e=s.employees.find(x=>x.id===t.employeeId),p=s.projects.find(x=>x.id===t.projectId);return `<article class="v8-row clickable" data-task="${esc(t.id)}"><div><b>${esc(t.title)}</b><small>${esc(e?.name||'غير مسند')} • ${esc(p?.name||'عام')}</small></div><span>${esc(status(t.status))}</span><strong>${Number(t.progress)||0}%</strong></article>`}
function reportRow(r,s){const p=s.projects.find(x=>x.id===r.projectId);return `<article class="v8-row clickable" data-report="${esc(r.id)}"><div><b>${esc(r.title)}</b><small>${esc(r.author||'AI')} • ${esc(p?.name||'عام')}</small></div><span>${esc(r.stage||'محفوظ')}</span><strong>فتح</strong></article>`}
function dashboard(s){return `${top('لوحة تشغيل الشركة','كل شيء المهم في مكان واحد، بدون 3D وبدون عناصر شكلية.')}${stats(s)}<section class="v8-grid"><div class="v8-card"><div class="v8-card-head"><h2>الموظفون</h2><span>اضغط على أي موظف لإعطائه أمر</span></div><div class="v8-people">${s.employees.map(person).join('')}</div></div><div class="v8-card"><div class="v8-card-head"><h2>المشاريع</h2><a href="apps.html">تطبيقاتي</a></div>${s.projects.slice(0,4).map(projectCard).join('')}</div></section><section class="v8-card"><div class="v8-card-head"><h2>آخر المهام</h2><button class="v8-btn" type="button" data-action="new-task">＋ مهمة جديدة</button></div><div class="v8-list">${s.tasks.slice(0,10).map(t=>taskRow(t,s)).join('')||'<div class="v8-empty">ما فيه مهام إلى الآن.</div>'}</div></section>`}
function workforce(s){return `${top('الموظفون','إدارة الفريق وإعطاء أوامر مباشرة لكل موظف.')}${stats(s)}<section class="v8-card"><div class="v8-card-head"><h2>فريقك (${s.employees.length})</h2><button class="v8-btn primary" type="button" data-action="new-employee">＋ إضافة موظف</button></div><div class="v8-people">${s.employees.map(person).join('')}</div></section>`}
function projects(s){return `${top('المشاريع','مُعين وقدّها وروابط التشغيل والإدارة المباشرة.')}${stats(s)}<section class="v8-card"><div class="v8-card-head"><h2>كل المشاريع</h2><a href="apps.html">مركز التطبيقات</a></div>${s.projects.map(projectCard).join('')}</section>`}
function tasks(s){return `${top('المهام','إنشاء، تشغيل، متابعة، وإعادة محاولة أي مهمة.')}${stats(s)}<section class="v8-card"><div class="v8-card-head"><h2>كل المهام (${s.tasks.length})</h2><button class="v8-btn primary" type="button" data-action="new-task">＋ مهمة جديدة</button></div><div class="v8-list">${s.tasks.map(t=>taskRow(t,s)).join('')||'<div class="v8-empty">ما فيه مهام إلى الآن.</div>'}</div></section>`}
function reports(s){return `${top('التقارير','نتائج الموظفين والمخرجات المحفوظة.')}${stats(s)}<section class="v8-card"><div class="v8-card-head"><h2>التقارير (${s.reports.length})</h2><span>تُنشأ تلقائيًا بعد إكمال المهام</span></div><div class="v8-list">${s.reports.map(r=>reportRow(r,s)).join('')||'<div class="v8-empty">ما فيه تقارير إلى الآن.</div>'}</div></section>`}
function render(){const s=seed(),root=$('#app');if(!root)return;let body=view==='dashboard'?dashboard(s):view==='workforce'?workforce(s):view==='projects'?projects(s):view==='tasks'?tasks(s):reports(s);root.innerHTML=`<div class="v8">${nav()}<main class="v8-main">${body}</main></div>`}
function ensureModal(){let m=$('#v8-modal');if(m)return m;m=document.createElement('div');m.id='v8-modal';m.className='v8-modal';m.innerHTML='<div class="v8-dialog"><div id="v8-modal-body"></div></div>';document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m||e.target.closest('[data-close]'))closeModal()});return m}
function openModal(html){const m=ensureModal();m.querySelector('#v8-modal-body').innerHTML=html;m.classList.add('show')}
function closeModal(){const m=$('#v8-modal');if(m)m.classList.remove('show')}
function toast(text){let t=$('.v8-toast');if(!t){t=document.createElement('div');t.className='v8-toast';document.body.appendChild(t)}t.textContent=text;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2200)}
function employeeModal(id){const s=read(),e=s.employees.find(x=>x.id===id);if(!e)return;openModal(`<div class="v8-dialog-head"><div><span class="v8-kicker">AI EMPLOYEE</span><h2>${esc(e.name)}</h2><small>${esc(e.role||e.department||'موظف AI')} • ${esc(status(e.status))}</small></div><button class="v8-close" data-close>×</button></div><form class="v8-form" id="v8-employee-edit-form"><label>الاسم<input name="name" required value="${esc(e.name||'')}"></label><label>المسمى الوظيفي<input name="role" required value="${esc(e.role||'')}"></label><label>القسم<input name="department" value="${esc(e.department||'')}"></label><label>المشروع الأساسي<select name="projectId"><option value="">بدون مشروع ثابت</option>${s.projects.map(p=>`<option value="${esc(p.id)}" ${e.projectId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="full">المهام / المسؤوليات الأساسية<textarea name="mission" rows="3" placeholder="اكتب مسؤوليات الموظف وما الذي يركز عليه افتراضيًا">${esc(e.mission||'')}</textarea></label><div class="full v8-modal-actions"><button class="v8-btn primary" type="submit">حفظ بيانات الموظف</button></div></form><div class="v8-command-types">${COMMANDS.map(([k,l])=>`<button type="button" data-command="${k}">${l}</button>`).join('')}</div><form class="v8-form" id="v8-command-form"><label>المشروع<select name="projectId"><option value="">عام / بدون مشروع</option>${s.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label>نوع التنفيذ<select name="kind"><option value="CUSTOM">تنفيذ مباشر</option><option value="RESEARCH">بحث</option><option value="REVIEW">مراجعة</option></select></label><label class="full">وش تبي ${esc(e.name)} يسوي؟<textarea name="details" rows="6" required placeholder="مثال: راجع تطبيق قدّها، أصلح مشكلة فتح الألعاب، وتأكد أن كل الألعاب تعمل."></textarea></label><div class="full v8-modal-actions"><button class="v8-btn" type="button" data-close>إلغاء</button><button class="v8-btn primary" type="submit">▶ ابدأ التنفيذ</button></div></form>`);$('#v8-employee-edit-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),q=read(),x=(q.employees||[]).find(v=>v.id===id);if(!x)return;x.name=String(f.get('name')||'').trim();x.role=String(f.get('role')||'').trim();x.department=String(f.get('department')||'').trim();x.projectId=String(f.get('projectId')||'');x.mission=String(f.get('mission')||'').trim();x.updatedAt=new Date().toISOString();write(q,'employee-updated');toast('تم حفظ تعديلات الموظف');render();employeeModal(id)};let selected='custom';$('[data-command]').forEach(b=>b.onclick=()=>{selected=b.dataset.command;$('[data-command]').forEach(x=>x.classList.toggle('active',x===b))});$('#v8-command-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),details=String(f.get('details')||'').trim();if(!details)return;createTask({employeeId:e.id,projectId:String(f.get('projectId')||''),details,kind:selected==='review'?'REVIEW':selected==='research'?'RESEARCH':selected.toUpperCase()});closeModal()}}
function newEmployee(){const s=read();openModal(`<div class="v8-dialog-head"><div><span class="v8-kicker">NEW AI EMPLOYEE</span><h2>إضافة موظف جديد</h2></div><button class="v8-close" data-close>×</button></div><form class="v8-form" id="v8-employee-form"><label>الاسم<input name="name" required placeholder="مثال: خالد"></label><label>المسمى الوظيفي<input name="role" required placeholder="مثال: مهندس برمجيات AI"></label><label>القسم<select name="department"><option>التقنية والبحث</option><option>المنتج والتجربة</option><option>الجودة والمراجعة</option><option>البحث</option><option>العمليات</option><option>الإدارة العامة</option></select></label><label>المشروع الأساسي<select name="projectId"><option value="">بدون مشروع ثابت</option>${s.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label class="full">المسؤولية<textarea name="mission" rows="4"></textarea></label><div class="full v8-modal-actions"><button class="v8-btn" type="button" data-close>إلغاء</button><button class="v8-btn primary" type="submit">إضافة الموظف</button></div></form>`);$('#v8-employee-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),q=read();q.employees.push({id:uid('emp'),name:String(f.get('name')).trim(),role:String(f.get('role')).trim(),department:String(f.get('department')),projectId:String(f.get('projectId')||''),mission:String(f.get('mission')||''),status:'READY',task:'',productivity:100,createdAt:new Date().toISOString()});write(q,'employee-created');closeModal();toast('تمت إضافة الموظف');render()}}
function newTask(){const s=read();openModal(`<div class="v8-dialog-head"><div><span class="v8-kicker">NEW TASK</span><h2>مهمة جديدة</h2></div><button class="v8-close" data-close>×</button></div><form class="v8-form" id="v8-task-form"><label>الموظف<select name="employeeId" required>${s.employees.map(e=>`<option value="${esc(e.id)}">${esc(e.name)} — ${esc(e.role||'')}</option>`).join('')}</select></label><label>المشروع<select name="projectId"><option value="">عام</option>${s.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label class="full">المهمة<textarea name="details" rows="6" required></textarea></label><div class="full v8-modal-actions"><button class="v8-btn" type="button" data-close>إلغاء</button><button class="v8-btn primary" type="submit">▶ إنشاء وتشغيل</button></div></form>`);$('#v8-task-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);createTask({employeeId:String(f.get('employeeId')),projectId:String(f.get('projectId')||''),details:String(f.get('details')||'').trim(),kind:'CUSTOM'});closeModal()}}
function companyCommand(){const first=read().employees?.[0];if(first)employeeModal(first.id)}
function createTask({employeeId,projectId,details,kind='CUSTOM'}){if(!details)return;const s=read(),e=s.employees.find(x=>x.id===employeeId);if(!e)return;const t={id:uid('t'),title:details.slice(0,90),details,employeeId,projectId,status:'READY',progress:0,kind,createdBy:'NAWAF',createdAt:new Date().toISOString()};s.tasks.unshift(t);e.status='READY';e.task=t.title;s.activity.unshift({id:uid('a'),text:`تم تكليف ${e.name}: ${t.title}`,type:'REAL',at:new Date().toISOString()});write(s,'task-created');render();toast(`تم إرسال المهمة إلى ${e.name}`);setTimeout(()=>runTask(t.id),120)}
async function runTask(id){const s=read(),t=s.tasks.find(x=>x.id===id);if(!t)return;try{if(t.projectId&&['mueen','qaddha'].includes(t.projectId)&&EXTERNAL.test(t.title+' '+t.details)&&window.NawafProjectExecutor?.runTask){await window.NawafProjectExecutor.runTask(id);return}if(window.NawafAgents?.runTask){await window.NawafAgents.runTask(id);return}if(window.NawafAgents?.runNext){await window.NawafAgents.runNext();return}throw new Error('محرك التنفيذ غير متاح')}catch(err){toast('تم حفظ المهمة، لكن محرك التنفيذ يحتاج إعادة محاولة')}}
function taskModal(id){const s=read(),t=s.tasks.find(x=>x.id===id);if(!t)return;const e=s.employees.find(x=>x.id===t.employeeId),p=s.projects.find(x=>x.id===t.projectId),result=t.aiResult?.deliverable||t.aiResult?.summary||t.blockedReason||'لا توجد نتيجة محفوظة بعد.',logs=Array.isArray(t.executionLog)?t.executionLog:[],evidence=Array.isArray(t.evidence)?t.evidence:[];openModal(`<div class="v8-dialog-head"><div><span class="v8-kicker">TASK</span><h2>${esc(t.title)}</h2><small>${esc(e?.name||'غير مسند')} • ${esc(p?.name||'عام')} • ${esc(status(t.status))}</small></div><button class="v8-close" data-close>×</button></div><div class="v8-result">${esc(result)}</div>${t.blockedReason?`<section class="v8-result"><b>العائق</b><p>${esc(t.blockedReason)}</p></section>`:''}<section class="v8-result"><b>سجل التنفيذ الحقيقي</b>${logs.length?logs.map(x=>`<p><small>${esc(x.stage)} • ${esc(x.at||'')}</small><br>${esc(x.detail||'')}</p>`).join(''):'<p>لم يبدأ التنفيذ بعد.</p>'}</section><section class="v8-result"><b>الأدلة (${evidence.length})</b>${evidence.length?evidence.map(x=>`<p>${esc(x.text||x)}</p>`).join(''):'<p>لا توجد أدلة محفوظة بعد.</p>'}</section><div class="v8-modal-actions"><button class="v8-btn" data-close>إغلاق</button>${t.status!=='COMPLETED'?`<button class="v8-btn primary" type="button" data-run-task="${esc(t.id)}">إعادة/بدء التنفيذ</button>`:''}</div>`)}
function projectModal(id){const s=read(),p=s.projects.find(x=>x.id===id);if(!p)return;const live=projectUrl(id),repo=repoUrl(id),tasks=s.tasks.filter(t=>t.projectId===id);openModal(`<div class="v8-dialog-head"><div><span class="v8-kicker">PROJECT</span><h2>${esc(p.name)}</h2><small>${esc(p.phase||'جاهز للعمل')} • ${tasks.length} مهمة</small></div><button class="v8-close" data-close>×</button></div><div class="v8-project-actions">${live?`<a href="${live}" target="_blank" rel="noopener noreferrer">فتح النسخة الحية</a>`:''}${repo?`<a href="${repo}" target="_blank" rel="noopener noreferrer">فتح GitHub</a>`:''}<button type="button" data-project-task="${esc(id)}">إعطاء مهمة على المشروع</button></div><div class="v8-list" style="margin-top:12px">${tasks.slice(0,8).map(t=>taskRow(t,s)).join('')||'<div class="v8-empty">ما فيه مهام للمشروع.</div>'}</div>`)}
function reportModal(id){const s=read(),r=s.reports.find(x=>x.id===id);if(!r)return;openModal(`<div class="v8-dialog-head"><div><span class="v8-kicker">REPORT</span><h2>${esc(r.title)}</h2><small>${esc(r.author||'AI')} • ${esc(r.stage||'محفوظ')}</small></div><button class="v8-close" data-close>×</button></div><div class="v8-result">${esc(r.content||'')}</div>`)}
document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v){view=v.dataset.view;if(VIEWS.includes(view))render();return}const a=e.target.closest('[data-action]');if(a){({"new-employee":newEmployee,"new-task":newTask,"company-command":companyCommand}[a.dataset.action])?.();return}const emp=e.target.closest('[data-employee]');if(emp){employeeModal(emp.dataset.employee);return}const p=e.target.closest('[data-project]');if(p){projectModal(p.dataset.project);return}const t=e.target.closest('[data-task]');if(t){taskModal(t.dataset.task);return}const r=e.target.closest('[data-report]');if(r){reportModal(r.dataset.report);return}const run=e.target.closest('[data-run-task]');if(run){closeModal();runTask(run.dataset.runTask);return}const pt=e.target.closest('[data-project-task]');if(pt){closeModal();const s=read(),emp=s.employees[0];if(emp){employeeModal(emp.id);setTimeout(()=>{const sel=$('#v8-command-form select[name="projectId"]');if(sel)sel.value=pt.dataset.projectTask},0)}return}});
let timer;window.addEventListener('nawaf:state-updated',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(!$('#v8-modal')?.classList.contains('show'))render()},180)});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',render);else render();
window.NawafHQV8={render,employee:employeeModal,newEmployee,newTask,runTask};
})();
